//! Actual Django model/form DateField vectors, generated by py/probe_dates.py.
#[test]
fn accepted_dates_and_errors_match_python() {
    let data: serde_json::Value = serde_json::from_str(include_str!("python_dates.json")).unwrap();
    type Parser = fn(&str) -> Result<chrono::NaiveDate, String>;
    let parsers: [(&str, Parser); 2] = [("model", fb_core::py::model_date), ("form", fb_core::py::form_date)];
    for (kind, parser) in parsers {
        for pair in data[kind].as_array().unwrap() {
            let value = pair[0].as_str().unwrap();
            let got = parser(value).map(|d: chrono::NaiveDate| d.to_string());
            if let Some(ok) = pair[1].get("ok") {
                assert_eq!(got.as_deref(), Ok(ok.as_str().unwrap()), "{kind}: {value:?}");
            } else {
                assert_eq!(got.as_ref().err().map(String::as_str), pair[1]["error"].as_str(), "{kind}: {value:?}");
            }
        }
    }
}
